    "{n} {w} для Windows, Android и Minecraft — выбирайте нужное.": ["{n} {w} для Windows, Android і Minecraft — обирайте потрібне.", "{n} {w} for Windows, Android and Minecraft — pick what you need."],
    "Открыть каталог": ["Відкрити каталог", "Open catalog"]
